def count_passengers_older_than_60(flights):
    """
    Counts the number of passengers older than 60 on a given list of flights.

    Args:
        flights (list): A list of dictionaries where each dictionary represents a flight and has 'passengers' as a key, 
                        where 'passengers' is a list of dictionaries with 'age' as a key.

    Returns:
        int: The total number of passengers older than 60.
