def faulty_keyboard(s):
    """
    Simulates the faulty keyboard by reversing the string whenever the character 'i' is encountered.

    Args:
    s (str): The input string to process.

    Returns:
    str: The final string after simulating the faulty keyboard.

    Raises:
    ValueError: If the input string length is not between 1 and 100.
    ValueError: If the input string contains any character other than lowercase English letters.
    """
