def count_pairs(s, queries):
    m, n = len(s), len(s[0])
    grid = [[int(c) for c in s]]

    # Apply prefix sum technique
    for _ in range(1, m):
        grid.append([grid[-1][i] + (grid[-1][i-1] if i > 0 else 0) for i in range(n)])

    results = []
    for l, r, c in queries:
        if c > 0:
            top = grid[r][c] - (grid[l][c] if l else 0)
            if grid[r][c] == grid[r][c-1]:
                top += 1
        else:
